CREATE OR REPLACE FUNCTION public.get_overtime_export_metadata_pt(p_worksite_id uuid, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_entry_time text DEFAULT NULL::text, p_departure_time text DEFAULT NULL::text, p_transport text DEFAULT 'all'::text, p_employee_search text DEFAULT ''::text, p_pt_search text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH base AS (SELECT entry_time,departure_time,status,needs_snack,needs_transport FROM public.overtime_requests WHERE worksite_id=p_worksite_id AND status<>'cancelled' AND (coalesce(trim(p_pt_search),'')='' OR position(lower(trim(p_pt_search)) in lower(coalesce(pt_number,'')))>0) AND (p_date_from IS NULL OR overtime_date>=p_date_from) AND (p_date_to IS NULL OR overtime_date<=p_date_to) AND (p_transport='all' OR (p_transport='yes' AND needs_transport) OR (p_transport='no' AND NOT needs_transport)) AND (coalesce(trim(p_employee_search),'')='' OR employee_name ILIKE '%'||trim(p_employee_search)||'%' OR employee_registration ILIKE '%'||trim(p_employee_search)||'%' OR employee_external_id ILIKE '%'||trim(p_employee_search)||'%')), summary AS (SELECT * FROM base WHERE (p_entry_time IS NULL OR entry_time=p_entry_time) AND (p_departure_time IS NULL OR departure_time=p_departure_time)) SELECT jsonb_build_object('entryTimes',coalesce((SELECT jsonb_agg(value ORDER BY value) FROM (SELECT DISTINCT entry_time AS value FROM base WHERE entry_time IS NOT NULL) q),'[]'::jsonb),'departureTimes',coalesce((SELECT jsonb_agg(value ORDER BY value) FROM (SELECT DISTINCT departure_time AS value FROM base WHERE departure_time IS NOT NULL AND (p_entry_time IS NULL OR entry_time=p_entry_time)) q),'[]'::jsonb),'kpis',jsonb_build_object('total',(SELECT count(*) FROM summary),'pending',(SELECT count(*) FROM summary WHERE status='pending'),'approved',(SELECT count(*) FROM summary WHERE status='approved'),'rejected',(SELECT count(*) FROM summary WHERE status='rejected'),'snacks',(SELECT count(*) FROM summary WHERE status='approved' AND needs_snack),'transports',(SELECT count(*) FROM summary WHERE status='approved' AND needs_transport))); $function$;
REVOKE ALL ON FUNCTION public.get_overtime_export_metadata_pt(uuid,date,date,text,text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_overtime_export_metadata_pt(uuid,date,date,text,text,text,text,text) TO service_role;
